/* @lc app=leetcode id=1865 lang=kotlin */ class FindSumPairs(val nums1: IntArray, val nums2: IntArray, val f: HashMap<Int, Int> = HashMap<Int, Int>().also { m -> nums2.forEach { m.merge(it, 1) { a, b -> a + b } } }) { fun add(index: Int, `val`: Int) { f.merge(nums2[index], -1) { a, b -> a + b }.also { nums2[index] += `val` }.also { f.merge(nums2[index], 1) { a, b -> a + b } } } fun count(tot: Int): Int = nums1.sumOf { f[tot - it] ?: 0 } }